OEVENTLUA[2925] = function ()
	Cls()
	dark()
	null(-2, 0)
	light()
	say("怎么这么多人？发生什么事了？", 0, 1)
	instruct_30(40, 30, 28, 30)
	instruct_25(28, 30, 19, 30)
	say("吴长老，你一向对丐帮忠心耿耿，为何今日要阴谋暗算传功、执法两位长老，你串联了这么多人，难道今日是要造反么？", 50, 0, "乔峰")
	say("乔帮主，我们大伙儿商量了，要废去你的帮主之位。这件大事，宋奚陈吴四长老都是参与的。我们怕传功、执法两位长老不允，是以设法将他们囚禁起来。这是为了本帮的大业着想，不得不冒险而为。今日势头不利，被你占了上风，我们由你处置便是。", 1152, 1, "吴长老")
	say("你这等行径，还配做丐帮的弟子吗？你自己了断呢？还是须得旁人动手？", 1235, 0, "白世镜")
	say("等等，吴长劳，全舵主，我乔峰自任帮主以来，为帮内兢兢业业，自认做事光明磊落，今日这许多好兄弟要反对我，这是什么原因？", 50, 1, "乔峰")
	say("乔帮主，今日是我等不对，你杀了我等便是。", 1152, 0, "吴长老")
	say("全舵主，你来说，我乔峰做了什么对不起众兄弟之事，你尽管当面指证，不必害怕，不用顾忌。", 50, 1, "乔峰")
	say("对不起众兄弟的大事，你现今虽然还没有做，但不久就要做了。", 1026, 0, "全冠清")
	say("胡说八道！乔帮主为人处事，光明磊落，他从前既没做过歹事，将来更加不会做。你只凭一些全无佐证的无稽之言，便煽动人心，意图背叛帮主。", 1235, 1, "白世镜")
	say("怎是全无佐证？马副帮主为人所害，我相信是出于乔峰的指使。", 1026, 0, "全冠清")
	say("你说什么？", 50, 1, "乔峰")
	say("报，马副帮主遗孀马夫人到。", 1104, 0, "丐帮弟子")
	dark()
	addevent(51, 19, 1, 0, 1, 8544, -2, -2)
	light()
	instruct_25(19, 30, 24, 30)
	say("各位伯伯叔叔，先夫不幸亡故，一直不知道是何人下的毒手？", 1224, 0, "马夫人")
	say("这是先夫秘藏的一封书信，还请各位伯伯叔叔观看，寻得凶手为我亡夫报仇。", 1224, 0, "马夫人")
	say("拿来我等看一看。", 1235, 1, "白世镜")
	say("是。", 1104, 0, "丐帮弟子")
	dark()
	light()
	instruct_25(24, 30, 19, 30)
	say("这个...", 1235, 1, "白世镜")
	say("拿来我看看。", 1249, 0, "徐长老")
	say("当日雁门关外血战，惊心动魄之状，余无日不萦于怀。此子非我族类，其父其母，死于我二人之手。他日此子不知其出身来历则已，否则不但丐帮将灭于其手，中原武林亦将遭逢莫大浩劫。", 1249, 1, "徐长老")
	say("这确是汪帮主的亲笔书信。", 1249, 0, "徐长老")
	say("唉，阿弥陀佛，阿弥陀佛。", 250, 1, "智光大师")
	say("如今丐帮已经内讧，情势紧急，智光大师，就请你把雁门关外乱石谷前的大战，讲述给大家听罢。", 1249, 0, "徐长老")
	say("唉，杀孽太重，杀孽太重……", 250, 1, "智光大师")
	say("好，老衲从前做错了事，也不必隐瞒，照实说来便是。那是三十年前，中原豪杰接到讯息，说契丹国有大批武士来偷袭少林，想将寺中秘藏数百年的武功图谱，一举夺去……", 250, 1, "智光大师")
	say("带头大哥带领我们赶赴雁门关阻击，终于将一队契丹人尽数杀死，不想最终发现似乎杀错了人。", 250, 1, "智光大师")
	say("啊", 0, 2)
	say("那似乎只是一队回家省亲的契丹贵族，最后只留下了一个契丹男孩，带头大哥心怀愧疚，将男孩带回中原，交给少室山下一个叫乔三槐的农人收养。", 250, 1, "智光大师")
	say("那，那是我的父亲，你胡说八道，捏造了这么一篇鬼话来诬陷我……", 50, 0, "乔峰")
	say("不错，谭氏伉俪，还有这位赵钱孙，当年都曾参加雁门关血战，难道大家都在一起骗你不成？乔峰，这是汪帮主的亲笔遗书，你自己看吧！", 250, 1, "智光大师")
	dark()
	light()
	say("这确是恩师亲笔，难道我真是契丹人？", 50, 0, "乔峰")
	say("是契丹人又如何？汉人也不是什么都好，契丹人也不是猪狗不如。明明是契丹人，却硬要冒充汉人。嘿嘿，嘿嘿……", 1149, 1, "赵钱孙")
	say("难怪我这些兄弟要反我，原来如此。", 50, 0, "乔峰")
	say("不错，非我族类，其心必异。你今日确是我们的好帮主，可难保日后不会帮契丹人对付我们汉人，丐帮乃是中原第一大帮，我们如何能让你再做帮主？", 1026, 1, "全冠清")
	say("原来如此，这丐帮帮主，我今日便不做了，众位长老，你们再推举一位新帮主出来，这是丐帮帮主信物打狗棒，白长老，你暂且收着，交给新任帮主。", 50, 0)
	say("帮主，你不要走，兄弟们都只服你，除了你，谁还有资格做丐帮帮主？", 1104, 1, "丐帮弟子")

	if JY.Person[0].门派 == 3 then
