OEVENTLUA[2980] = function ()
	Cls()
	dark()
	null(-2, 142)
	null(51, 0)
	light()
	say("少林寺门外这么多的人啊", 0, 1)
	instruct_30(53, 19, 48, 19)
	instruct_30(48, 19, 48, 32)
	meet_self(48)
	say("少林寺玄慈方丈，少林派是武林中各门派之首，丐帮是江湖第一大帮，数百年来并峙中原，不相统属。", 48, 1, "游坦之")
	say("今日咱们要分个高下，胜者为武林盟主，带领大伙儿保国安民，败者服从武林盟主号令，不得有违。", 48, 1, "游坦之")
	say("天下各位英雄好汉，今日都聚集在少室山上，有哪一位不服，尽可向武林盟主挑战。", 48, 1, "游坦之")
	say("阿弥陀佛。丐帮数百年来，乃中原武林的侠义正道，天下英雄，无不敬仰。", 70, 0)
	say("贵帮推举新帮主，敝派得讯迟了，未及遣使道贺，不免有简慢之罪，谨此谢过。", 70, 0)
	say("贵帮前任帮主汪剑通帮主，与敝派交情着实不浅。却不知帮主今日何以忽兴问罪之师，还盼见告。天下英雄，俱在此间，是非曲直，自有公论。", 70, 0)
	say("＜少林方丈，果然是不简单＞", 48, 1, "游坦之")
	say("我中原北有辽国，西有西夏、吐蕃，南有大理，四夷虎视眈眈。", 48, 1, "游坦之")
	say("然我中原兵微将寡，国势脆弱，全赖我武林义士，江湖同道，大伙儿一同匡扶，这才能外抗强敌，内除奸人。", 48, 1, "游坦之")
	say("〔众人〕不错，不错。", 0, 2)
	say("只不过近年来外患日深，大伙儿本当齐心合力，共赴艰危。可是各门各派，各帮各会，却你争我斗，不能够齐心。", 48, 1, "游坦之")
	say("契丹人乔峰单枪匹马地来聚贤庄一闹，中原豪杰便一败涂地。又听说西域星宿海的星宿老怪曾连杀少林派的两名高僧，少林派束手无策……", 48, 1, "游坦之")
	say("阿弥陀佛。老衲两位师弟不幸为奸人所害，着实令人心痛。然敝派正在商议对策，不劳外人费心。", 70, 0)
	say("方丈此言差矣。我中原步步艰危，江湖同道却又不能齐心合力，以致常受番邦欺压。", 48, 1, "游坦之")
	say("因此丐帮主张立一位武林盟主，大伙儿听奉号令，有什么大事发生，便不致乱成一团了。", 48, 1, "游坦之")
	say("玄慈大师，你只需胜得了在下，丐帮便唯少林马首是瞻，从此并肩抗敌。", 48, 1, "游坦之")
	say("此乃造福中原武林，造福黎民百姓之举，望方丈勿再碍于门派，身份之见，阻挠利于天下苍生的大业。", 48, 1, "游坦之")
	say("〔众人〕丐帮帮主的话，确实有些道理。", 0, 2)
	say("帮主的话，倒也言之成理。阁下既非要老衲出手不可，老衲若再顾念贵帮和敝派数百年的交情，坚不肯允，倒是对贵帮不敬了。", 70, 0)
	say("老衲今日便以本派大金刚掌接一接帮主的降龙十八掌绝技，也好让天下英雄好汉，瞧瞧丐帮帮主数百年来的嫡传功夫。", 70, 0)
	say("＜这老和尚一定是明知我不会降龙十八掌，故意将我一军＞", 48, 1, "游坦之")
	say("降龙十八掌只是二流功夫，怎么比得上我们帮主的逍遥游。", 207, 4, "丐帮弟子")
	say("谁说降龙十八掌只是二流功夫。", 50, 0)
	dark()
	addevent(-2, 71, 1, nil, nil, 6294)
	addevent(-2, 68, 1, nil, nil, 10328)
	addevent(-2, 69, 1, nil, nil, 10328)
	light()

	if JY.Person[50].好感度 <= 30 then
		say("萧峰居然来了，且找个机会做掉他。", 0, 1)
	end

	say("〔小部分丐帮帮众〕乔帮主，乔帮主来了！", 0, 2)
	say("契丹人萧峰已给丐帮逐出，与丐帮更无瓜葛。众位何得仍用旧日称呼，众位兄弟，别来俱都安好？", 50, 0)
	say("〔小部分丐帮帮众〕乔……乔……你老人家好，自别之后，咱们无日不……不想念你老人家。", 0, 2)
	say("大哥，别来可好，这可想煞小弟了。", 53, 4)
	say("兄弟，别来多事，一言难尽，差幸你我俱都安好。", 50, 0)
	say("〔众人〕姓乔的，你杀了我的兄长，血仇未曾得报，今日和你拼了！", 0, 2)
	say("〔众人〕这乔峰乃契丹胡虏，人人得而诛之，今日可再也不能容他活着走下少室山！", 0, 2)
	say("＜今日本想暗中探访\"带头大哥\"的身份，想不到少室山上竟有这许多对头聚在一起。＞", 50, 0)
	say("＜眼下一场恶战在所难免，能否全身而退殊难预料，何必搭上段誉兄弟)＞", 50, 0)
	say("兄弟，此时局面恶劣，你我兄弟难以多叙，你暂且退开，山高水长，后会有期。", 50, 0)
	say("大哥，做兄弟的跟你结义之时，说什么来着？", 53, 4)
	say("咱俩有福同享，有难同当，不求同年同月同日生，但愿同年同月同日死。今日大哥有难，兄弟安能苟且偷生。", 53, 4)
	say("兄弟，你的好意，哥哥甚是感谢。他们想要杀我，却也没这么容易。你快退开，否则我要分手护你，反而不便迎敌。", 50, 0)
	say("你不用护我，他们和我无怨无仇，如何便来杀我？", 53, 4)
	say("＜轻轻摇头，心头苦涩：倘若无怨无仇便不构陷加害，世间种种恶行，估计可以消去大半了＞", 50, 0)
	say("杀父之仇，不共戴天。姓萧的，咱们今日便来做个了断！", 48, 1, "游坦之")
	WarMain(249, 0)
	say("＜这乔峰如今已被逐出丐帮，成为中原武林的公敌，我正好趁此机会，收揽人心，以为己助＞", 51, 0)
	say("萧兄，你是契丹英雄，视我中原豪杰有如无物，区区姑苏慕容复今日想领教阁下高招。", 51, 0)
	say("在下死在萧兄掌下，也算是为中原豪杰尽了一分微力，虽死犹荣。", 51, 0)
	say("慕容兄，这可就是你的不是了。我大哥和你素无嫌隙，你又何必乘人之危。", 53, 4)
	say("段兄要做打抱不平的英雄好汉，一并上来赐教便是。", 51, 0)
	say("我有什么本领来赐教于你？只不过说句公道话罢了。", 53, 4)
	say("段郎，你不要和我表哥打。", 76, 0, "王语嫣")
	say("放心，我只要救我大哥，等会我避着他就是。", 53, 4)

