		say("住手，萧大哥是好人，你们不要围攻他！", 49, 0, "虚竹")
		say("虚竹，你是少林弟子，怎可相助这个契丹人，你留在后边，不要上来。", 70, 1, "玄慈")
		say("我，方丈。你们不能杀我大哥。", 49, 0, "虚竹")
	end

	WarMain(250, 0)
	dark()
	null(-2, 59)
	null(-2, 71)
