	addevent(-2, 124, 1, nil, nil, 6302)
	say("我", 51, 0, "慕容复")
	say("我居然在群豪面前被打败了，真是丢脸啊。王图霸业，今日休咿！", 51, 0, "慕容复")
	addevent(-2, 124, 1, nil, nil, 6286)
	say("便在此时，只听得破空声大作，一件暗器从十余丈外飞来，横过广场，撞向慕容复手中长剑，铮的一声响，慕容复长剑脱手飞出，手掌中满是鲜血，虎口已然震裂", 0, 2)
	addevent(-2, 126, 1, nil, nil, 8848)
	addevent(-2, 124, 1, nil, nil, 6300)
	meet_self(113)
	say("你有儿子没有？", 113, 0, "慕容博")
