	say("自然有！我自愿就死，与你何干？士可杀不可辱，慕容复堂堂男子，受不得你这些无礼的言语。", 51, 1, "慕容复")
	say("你高祖有儿子，你曾祖、祖父、父亲都有儿子，便是你没有儿子！嘿嘿，大燕国当年慕容皝、慕容恪、慕容垂、慕容德何等英雄，却不料都变成了断种绝代的无后之人！", 113, 0, "慕容博")
	say("先父昔年谆谆告诫，命我以兴复大燕为终生之志，今日我以一时之忿，自寻短见，我鲜卑慕容氏从此绝代。我连儿子也没有，还说得上甚么光宗复国？", 51, 1, "慕容复")
	say("慕容复识见短绌，得蒙高僧指点迷津，大恩大德，没齿难忘。", 51, 1, "慕容复")
	say("古来成大功业者，哪一个不历尽千辛万苦？汉高祖有白登求和之困，唐高祖有降顺突厥之辱，倘若都似你这么引剑一割，只不过是个心窄气狭的自了汉罢了，还谈得上甚么开国建基？你连勾践、韩信也不如，当真是无知无识之极。", 113, 0, "慕容博")
